// Network Transport feature module. Validated runtime configuration.
namespace ClearGameEngine.RootFeatures;
public sealed class NetworkTransportFeature:FeatureModuleBase{public const string FeatureId="network-transport";public NetworkTransportFeature():base(FeatureId,"Network Transport",new FeatureSetting("budget","Network Transport budget",768,1,100000),new FeatureSetting("quality","Quality level",2,0,4)){} public int Budget{get=>TryGet("budget",out var v)?(int)v:768;set=>TrySet("budget",value);} public int Quality{get=>TryGet("quality",out var v)?(int)v:2;set=>TrySet("quality",value);} public bool IsConfigured=>Validate(out _);}
